274	// 等待被挂起的保存请求出现（页面已发出请求、服务尚未给出结果）
275	async function waitForHeld(session, timeout = 5000) {
276	  const deadline = Date.now() + timeout;
277	  while (Date.now() < deadline) {
278	    if (session.held.length > 0) return session.held[0];
279	    await new Promise(r => setTimeout(r, 25));
280	  }
281	  throw new Error("保存请求未在限定时间内发出");
282	}
