322	function cleanedUp(snap) {
323	  return snap.selCount === "0" &&
324	    snap.selNoneHint && snap.selChips.length === 0 &&
325	    !snap.checkAllChecked && !snap.checkAllIndeterminate &&
326	    snap.rows.every(r => !r.checked && !r.selected) &&
327	    snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled) &&
328	    snap.submitText === "保存修改" && snap.submitDisabled;
