331	// 「结果无法确认」横幅：bad 类；明确无法确认、提醒先核对客户列表再决定是否重新保存；
332	// 不出现成功数量；不做「全部拒绝/资料保持原样」的肯定结论；不自动重发。
333	// （文案可以、也应当明确否定「未修改/已回滚」，故不把这些词本身列为违禁。）
334	function unconfirmedBanner(snap) {
335	  return snap.banners.length === 1 && snap.banners[0].cls.includes("bad") &&
336	    snap.banners[0].text.includes("无法确认") &&
337	    snap.banners[0].text.includes("核对客户列表") &&
338	    /重新保存/.test(snap.banners[0].text) &&
339	    snap.banners[0].text.includes("不会自动重新提交") &&
340	    !/已成功处理/.test(snap.reportText) &&
341	    !/全部拒绝/.test(snap.reportText) &&
342	    !/保持原样/.test(snap.reportText);
343	}
