345	// 无法确认时不做保存成功后的清理：勾选、字段操作与已填内容原样保留
346	function retainedState(snap, {count, ops}) {
347	  return snap.selCount === String(count) &&
348	    snap.rows.filter(r => r.checked).length === count &&
349	    ops.every(([key, op, value]) => {
350	      const f = snap.fields.find(x => x.key === key);
351	      return f && f.op === op && (value === undefined || f.value === value);
352	    }) &&
353	    snap.submitText === "保存修改" && !snap.submitDisabled;
354	}
