import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, rmSync, writeFileSync, mkdirSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";

const HERE = "/opt/gsb-production/workspaces/coco/prod-18/B/task024";
const TMP = mkdtempSync(join(tmpdir(), "probe-"));
const proc = spawn("python3", [join(HERE, "app.py"), "serve", "--host", "127.0.0.1", "--port", "0", "--data-dir", join(TMP, "d")], {cwd: HERE, stdio: ["ignore","pipe","pipe"]});
let buf = "";
const port = await new Promise((resolve, reject) => {
  proc.stdout.on("data", d => { buf += d; const m = buf.match(/:(\d+)/); if (m) resolve(Number(m[1])); });
  proc.on("exit", c => reject(new Error("exit " + c)));
});
const base = `http://127.0.0.1:${port}`;
await new Promise(r => setTimeout(r, 500));

const browser = await puppeteer.launch({executablePath: "/usr/bin/google-chrome", headless: true, args: ["--no-sandbox"]});
const page = await browser.newPage();
let held = null;
await page.setRequestInterception(true);
page.on("request", request => {
  if (request.method() === "POST" && request.url().endsWith("/api/clients/import")) {
    held = request;
    return;
  }
  request.continue();
});
await page.goto(base + "/", {waitUntil: "networkidle0"});
mkdirSync(join(TMP, "u"), {recursive: true});
const p = join(TMP, "u", "first.csv");
writeFileSync(p, "name\n首次客户甲\n首次客户乙\n", "utf8");
await page.$("#file-input").then(i => i.uploadFile(p));
await page.click("#submit-btn");
await new Promise(r => setTimeout(r, 500));
console.log("postData() type:", typeof held.postData(), held.postData() && JSON.stringify(held.postData()).slice(0,120));
try {
  const fd = await held.fetchPostData();
  console.log("fetchPostData():", JSON.stringify(fd).slice(0,120));
} catch (e) {
  console.log("fetchPostData() threw:", e.message);
}
held.continue();
await new Promise(r => setTimeout(r, 300));
await browser.close();
proc.kill();
await new Promise(r => proc.on("exit", r));
rmSync(TMP, {recursive: true, force: true});
EOF
