async function waitForHeld(list, timeout = 5000) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    if (list.length > 0) return list[0];
    await new Promise(r => setTimeout(r, 25));
  }
  throw new Error("挂起的请求未在限定时间内出现");
}

