    {err: rsnap.loadErrorOn, rows: rsnap.rows.map(r => r.cells[0])});
  check("L 重新打开：不会自动重新导入",
    reopened.counts.importPosts === 0, `posts=${reopened.counts.importPosts}`);
  await page.close();
  await reopened.page.close();
}

await browser.close();

