cd /opt/gsb-production/workspaces/coco/prod-18/B/task024
cat > probe2_tmp.mjs <<'EOF'
import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, rmSync, writeFileSync, mkdirSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";
const HERE = process.cwd();
const TMP = mkdtempSync(join(tmpdir(), "probe2-"));
const proc = spawn("python3", [join(HERE,"app.py"),"serve","--host","127.0.0.1","--port","0","--data-dir",join(TMP,"d")],{cwd:HERE,stdio:["ignore","pipe","pipe"]});
let buf="";
const port = await new Promise((res,rej)=>{proc.stdout.on("data",d=>{buf+=d;const m=buf.match(/:(\d+)/);if(m)res(Number(m[1]));});});
const base=`http://127.0.0.1:${port}`;
await new Promise(r=>setTimeout(r,400));
const browser = await puppeteer.launch({executablePath:"/usr/bin/google-chrome",headless:true,args:["--no-sandbox"]});
const page=await browser.newPage();
await page.setRequestInterception(true);
let held=null;
page.on("request",req=>{
  if(req.method()==="POST"&&req.url().endsWith("/api/clients/import")){held=req;return;}
  req.continue();
});
await page.goto(base+"/",{waitUntil:"networkidle0"});
mkdirSync(join(TMP,"u"),{recursive:true});
const p1=join(TMP,"u","first.csv"), p2=join(TMP,"u","later.csv");
writeFileSync(p1,"name\n首次唯一甲\n首次唯一乙\n","utf8");
writeFileSync(p2,"name\n后来唯一丙\n","utf8");
const up=async p=>{await page.$("#file-input").then(i=>i.uploadFile(p));};
await up(p1);
// 模拟：提交时记住 files[0]，2 秒后才发起 fetch（懒读取当时的控件）
await page.evaluate(() => {
  const input=document.getElementById("file-input");
  document.getElementById("import-form").addEventListener("submit", async e => {
    e.preventDefault();
    await new Promise(r=>setTimeout(r,1500));
    fetch("/api/clients/import",{method:"POST",body:input.files[0]});
  }, {capture:true});
});
await page.click("#submit-btn");
await new Promise(r=>setTimeout(r,300));
await up(p2);   // 等待期间另选 later
console.log("held before 1.5s?", !!held);
await new Promise(r=>setTimeout(r,1600));
console.log("held after 1.5s?", !!held);
held.continue();
await new Promise(r=>setTimeout(r,500));
const r=await fetch(base+"/api/clients");
console.log("backend clients:", (await r.json()).clients.map(x=>x.name));
await browser.close(); proc.kill(); await new Promise(rr=>proc.on("exit",rr)); rmSync(TMP,{recursive:true,force:true});
EOF
node probe2_tmp.mjs; rm -f probe2_tmp.mjs

